// localStorage — persists until explicitly cleared
localStorage.setItem('theme', 'dark');
localStorage.setItem('fontSize', '16');

const theme = localStorage.getItem('theme'); // 'dark'
const missing = localStorage.getItem('xyz'); // null

localStorage.removeItem('theme');   // delete one key
localStorage.clear();               // delete everything

// Store objects (JSON serialization required)
localStorage.setItem('user', JSON.stringify({ name: 'Alice', score: 95 }));
const user = JSON.parse(localStorage.getItem('user'));

// sessionStorage — same API, but clears when tab closes
sessionStorage.setItem('currentStep', '3');
sessionStorage.getItem('currentStep'); // '3'
// → null after tab is closed and reopened
